## 二、LED控制

### 2.1 点亮单个LED

#### 2.1.1 硬件原理

LED（发光二极管）是一种半导体发光器件，具有以下特性：
- **正向电压**：红色LED约2V，绿色LED约2.2V
- **工作电流**：通常为10-20mA
- **限流电阻**：需要串联电阻限制电流

**连接方式：**
- **共阳极**：所有LED的阳极连接在一起，接VCC
- **共阴极**：所有LED的阴极连接在一起，接GND

#### 2.1.2 代码实现

```c
#include <reg52.h>  // 包含51单片机头文件，定义了特殊功能寄存器

void main()  // 主函数，程序入口
{
    P1 = 0xFE;  // 将P1端口设置为11111110，点亮P1.0连接的LED
    // 0xFE = 11111110，最低位为0，其他位为1
    // 0表示输出低电平，1表示输出高电平
    // 共阳极LED：低电平点亮，高电平熄灭

    while(1)  // 无限循环，保持程序运行
    {
        // 空循环，保持LED常亮
    }
}
```

#### 2.1.3 代码详解

```c
#include <reg52.h>  // 包含reg52.h头文件，定义了51单片机的特殊功能寄存器
// reg52.h包含了P0、P1、P2、P3等端口的定义
// 也包含了定时器、中断、串口等寄存器的定义

void main()  // 定义主函数main，程序的执行入口
{  // 主函数开始
    P1 = 0xFE;  // 向P1端口写入数据0xFE
    // P1是8位并行端口，可以同时控制8个LED
    // 0xFE转换为二进制：11111110
    // 每个位对应一个LED的开关状态
    // 0表示输出低电平，1表示输出高电平

    while(1)  // while循环，条件永远为真
    {  // 循环体开始
        // 空语句，什么都不做
        // 保持程序运行，不会退出
    }  // 循环体结束
}  // 主函数结束
```

### 2.2 LED闪烁控制

#### 2.2.1 延时函数实现

```c
#include <reg52.h>  // 包含51单片机头文件

// 延时函数声明
void 延时(unsigned int 延时时间);  // 声明延时函数，参数为无符号整型

void main()  // 主函数
{
    while(1)  // 无限循环
    {
        P1 = 0xFE;  // 点亮LED，输出低电平
        // 0xFE = 11111110，P1.0为低电平

        延时(50000);  // 调用延时函数，延时约50000个循环
        // 延时时间取决于单片机频率和循环次数

        P1 = 0xFF;  // 熄灭LED，输出高电平
        // 0xFF = 11111111，所有端口为高电平

        延时(50000);  // 再次延时
        // 控制LED闪烁的频率
    }
}

// 延时函数定义
void 延时(unsigned int 延时时间)  // 定义延时函数
{
    unsigned int 计数器;  // 定义计数器变量
    // 用于控制延时循环的次数

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)  // for循环
    // 从0开始，每次加1，直到达到延时时间
    {
        // 空循环体，消耗CPU时间
        // 循环次数越多，延时时间越长
    }
}
```

#### 2.2.2 代码详解

```c
#include <reg52.h>  // 包含51单片机头文件，定义特殊功能寄存器

void 延时(unsigned int 延时时间);  // 声明延时函数原型
// void表示函数没有返回值
// unsigned int表示参数是无符号整型，范围0-65535
// 延时时间是函数的形参，用于接收实际参数

void main()  // 主函数定义
{
    while(1)  // 无限循环，条件永远为真
    {
        P1 = 0xFE;  // 点亮P1.0连接的LED
        // 0xFE = 11111110，P1.0输出低电平
        // 共阳极LED，低电平点亮

        延时(50000);  // 调用延时函数，实参为50000
        // 函数调用，传递参数50000给延时函数
        // 延时约50000个机器周期

        P1 = 0xFF;  // 熄灭所有LED
        // 0xFF = 11111111，所有端口输出高电平
        // 共阳极LED，高电平熄灭

        延时(50000);  // 再次调用延时函数
        // 控制LED闪烁的间隔时间
    }
}

void 延时(unsigned int 延时时间)  // 延时函数定义
{
    unsigned int 计数器;  // 定义循环计数器变量
    // 用于控制循环次数，实现延时效果

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)  // for循环
    // 计数器从0开始，每次增加1，直到等于延时时间
    // 循环体为空，只消耗CPU时间
    {
        // 空语句，什么都不做
        // 通过循环次数控制延时时间
    }
}
```

### 2.3 流水灯实现

#### 2.3.1 基础流水灯

```c
#include <reg52.h>  // 包含51单片机头文件

void 延时(unsigned int 延时时间);  // 延时函数声明

void main()  // 主函数
{
    unsigned char 流水灯模式 = 0xFE;  // 定义流水灯模式变量，初始值0xFE
    // unsigned char是无符号字符型，范围0-255
    // 0xFE = 11111110，点亮第一个LED

    while(1)  // 无限循环
    {
        P1 = 流水灯模式;  // 将流水灯模式输出到P1端口
        // 控制LED的亮灭状态

        延时(30000);  // 延时，控制流水灯速度
        // 延时时间越长，流水灯移动越慢

        流水灯模式 = (流水灯模式 << 1) | 0x01;  // 流水灯模式左移1位
        // <<是左移运算符，将二进制位向左移动
        // |是按位或运算符，用于保持最低位为1
        // 实现LED从右向左移动的效果

        if(流水灯模式 == 0xFF)  // 判断是否回到初始状态
        // 当流水灯模式为0xFF时，表示所有LED都熄灭
        {
            流水灯模式 = 0xFE;  // 重置流水灯模式
            // 重新开始流水灯效果
        }
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;  // 定义计数器变量

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)  // for循环
    {
        // 空循环，消耗CPU时间
    }
}
```

#### 2.3.2 双向流水灯

```c
#include <reg52.h>  // 包含51单片机头文件

void 延时(unsigned int 延时时间);  // 延时函数声明

void main()  // 主函数
{
    unsigned char 流水灯模式 = 0xFE;  // 流水灯模式变量
    unsigned char 方向 = 0;  // 方向标志，0表示向左，1表示向右

    while(1)  // 无限循环
    {
        P1 = 流水灯模式;  // 输出流水灯模式到P1端口
        延时(20000);  // 延时控制速度

        if(方向 == 0)  // 判断方向
        {
            流水灯模式 = (流水灯模式 << 1) | 0x01;  // 向左移动
            // 左移运算，实现LED从右向左移动

            if(流水灯模式 == 0xFF)  // 判断是否到达最左边
            {
                方向 = 1;  // 改变方向为向右
                流水灯模式 = 0x7F;  // 设置为最左边LED点亮
                // 0x7F = 01111111
            }
        }
        else  // 向右移动
        {
            流水灯模式 = (流水灯模式 >> 1) | 0x80;  // 向右移动
            // >>是右移运算符，将二进制位向右移动
            // 0x80 = 10000000，保持最高位为1

            if(流水灯模式 == 0xFF)  // 判断是否到达最右边
            {
                方向 = 0;  // 改变方向为向左
                流水灯模式 = 0xFE;  // 设置为最右边LED点亮
            }
        }
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

#### 2.3.3 代码详解

```c
#include <reg52.h>  // 包含51单片机头文件，定义特殊功能寄存器

void 延时(unsigned int 延时时间);  // 声明延时函数

void main()  // 主函数，程序入口
{
    unsigned char 流水灯模式 = 0xFE;  // 定义流水灯模式变量
    // unsigned char：无符号字符型，占1字节，范围0-255
    // 0xFE = 11111110，初始状态点亮P1.0连接的LED
    // 0表示低电平（LED亮），1表示高电平（LED灭）

    unsigned char 方向 = 0;  // 定义方向标志变量
    // 0表示从右向左移动，1表示从左向右移动
    // 用于控制流水灯的移动方向

    while(1)  // 无限循环，条件永远为真
    {
        P1 = 流水灯模式;  // 将流水灯模式输出到P1端口
        // P1是8位并行端口，可以同时控制8个LED
        // 每个位对应一个LED的亮灭状态

        延时(20000);  // 调用延时函数，延时20000个循环
        // 控制流水灯的移动速度
        // 延时时间越长，移动速度越慢

        if(方向 == 0)  // 判断当前移动方向
        {
            流水灯模式 = (流水灯模式 << 1) | 0x01;  // 向左移动
            // <<是左移运算符，将二进制位向左移动1位
            // 例如：11111110 << 1 = 11111100
            // |是按位或运算符，与0x01进行或运算
            // 0x01 = 00000001，保持最低位为1

            if(流水灯模式 == 0xFF)  // 判断是否到达最左边
            // 0xFF = 11111111，所有LED都熄灭
            {
                方向 = 1;  // 改变移动方向为向右
                // 方向标志设置为1，表示向右移动

                流水灯模式 = 0x7F;  // 设置为最左边LED点亮
                // 0x7F = 01111111，点亮P1.7连接的LED
            }
        }
        else  // 向右移动
        {
            流水灯模式 = (流水灯模式 >> 1) | 0x80;  // 向右移动
            // >>是右移运算符，将二进制位向右移动1位
            // 例如：01111111 >> 1 = 00111111
            // 0x80 = 10000000，保持最高位为1

            if(流水灯模式 == 0xFF)  // 判断是否到达最右边
            {
                方向 = 0;  // 改变移动方向为向左
                // 方向标志设置为0，表示向左移动

                流水灯模式 = 0xFE;  // 设置为最右边LED点亮
                // 0xFE = 11111110，点亮P1.0连接的LED
            }
        }
    }
}

void 延时(unsigned int 延时时间)  // 延时函数定义
{
    unsigned int 计数器;  // 定义循环计数器变量
    // 用于控制循环次数，实现延时效果

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)  // for循环
    // 计数器从0开始，每次增加1，直到等于延时时间
    {
        // 空循环体，只消耗CPU时间
        // 循环次数越多，延时时间越长
    }
}
```

### 2.4 PWM调光

#### 2.4.1 PWM原理

PWM（脉冲宽度调制）是一种通过改变脉冲宽度来控制平均电压的技术：
- **占空比**：高电平时间占总周期的比例
- **频率**：脉冲每秒重复的次数
- **应用**：LED调光、电机调速、舵机控制

#### 2.4.2 软件PWM实现

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED = P1^0;  // 定义LED连接的引脚
// sbit用于定义特殊功能位，访问单个引脚
// P1^0表示P1端口的第0位

void 延时(unsigned int 延时时间);  // 延时函数声明

void main()  // 主函数
{
    unsigned char 占空比 = 50;  // 定义占空比变量，初始值50%
    // 占空比范围0-100，表示高电平占周期的百分比

    unsigned char 循环计数器;  // 定义循环计数器
    // 用于PWM循环控制

    while(1)  // 无限循环
    {
        // PWM高电平部分
        LED = 0;  // LED点亮，输出低电平
        // 共阳极LED，低电平点亮

        for(循环计数器 = 0; 循环计数器 < 占空比; 循环计数器++)  // 高电平循环
        {
            延时(100);  // 延时，控制高电平持续时间
            // 延时时间乘以占空比等于高电平总时间
        }

        // PWM低电平部分
        LED = 1;  // LED熄灭，输出高电平
        // 共阳极LED，高电平熄灭

        for(循环计数器 = 0; 循环计数器 < (100 - 占空比); 循环计数器++)  // 低电平循环
        {
            延时(100);  // 延时，控制低电平持续时间
            // 延时时间乘以(100-占空比)等于低电平总时间
        }
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

#### 2.4.3 渐变调光

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED = P1^0;  // 定义LED引脚

void 延时(unsigned int 延时时间);  // 延时函数声明

void main()  // 主函数
{
    unsigned char 占空比 = 0;  // 占空比变量，初始值0%
    unsigned char 方向 = 0;  // 方向标志，0表示增加，1表示减少
    unsigned char 循环计数器;  // 循环计数器

    while(1)  // 无限循环
    {
        // 生成PWM波形
        LED = 0;  // LED点亮

        for(循环计数器 = 0; 循环计数器 < 占空比; 循环计数器++)
        {
            延时(100);
        }

        LED = 1;  // LED熄灭

        for(循环计数器 = 0; 循环计数器 < (100 - 占空比); 循环计数器++)
        {
            延时(100);
        }

        // 调整占空比，实现渐变效果
        if(方向 == 0)  // 增加亮度
        {
            占空比++;  // 占空比加1
            // 每次循环增加1%，逐渐变亮

            if(占空比 >= 100)  // 判断是否达到最大亮度
            {
                方向 = 1;  // 改变方向为减少亮度
            }
        }
        else  // 减少亮度
        {
            占空比--;  // 占空比减1
            // 每次循环减少1%，逐渐变暗

            if(占空比 <= 0)  // 判断是否达到最小亮度
            {
                方向 = 0;  // 改变方向为增加亮度
            }
        }

        延时(1000);  // 延时，控制渐变速度
        // 延时时间越长，渐变速度越慢
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

