#### 3.2.2 定时器消抖

```c
#include <reg52.h>  // 包含51单片机头文件

sbit 按键 = P3^0;  // 定义按键引脚
sbit LED = P1^0;  // 定义LED引脚

unsigned char 按键状态 = 0;  // 按键状态变量
unsigned char 按键计数器 = 0;  // 按键计数器
unsigned char 按键稳定 = 0;  // 按键稳定标志

void 定时器0初始化()  // 定时器0初始化函数
{
    TMOD = 0x01;  // 设置定时器0为模式1
    // 0x01 = 00000001
    // 定时器0工作在模式1(16位定时器)
    // 定时器1保持不变

    TH0 = 0xFC;  // 设置定时器0高8位
    // 定时器初值，决定定时时间
    // 0xFC = 11111100

    TL0 = 0x18;  // 设置定时器0低8位
    // 0x18 = 00011000
    // 定时时间约为1ms

    TR0 = 1;  // 启动定时器0
    // TR0是定时器0运行控制位
    // 1表示启动，0表示停止

    ET0 = 1;  // 允许定时器0中断
    // ET0是定时器0中断允许位
    // 1表示允许中断，0表示禁止中断

    EA = 1;  // 开启总中断
    // EA是总中断允许位
    // 1表示开启总中断，0表示关闭总中断
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0xFC;  // 重新加载定时器初值
    // 定时器中断后需要重新设置初值

    TL0 = 0x18;  // 重新加载定时器初值
    // 保持定时时间一致

    if(按键 == 0)  // 检测按键状态
    {
        按键计数器++;  // 按键计数器加1
        // 记录按键按下的时间

        if(按键计数器 > 10)  // 判断按键是否稳定
        // 连续检测10次(10ms)按键都为低电平
        {
            按键稳定 = 1;  // 设置按键稳定标志
            // 表示按键确实按下，不是抖动
        }
    }
    else  // 按键释放
    {
        if(按键稳定 == 1)  // 判断按键是否曾经稳定
        {
            按键状态 = ~按键状态;  // 按键状态取反
            // 切换按键状态标志
        }

        按键计数器 = 0;  // 清零按键计数器
        // 重置计数器，准备下一次检测

        按键稳定 = 0;  // 清零按键稳定标志
        // 重置稳定标志
    }
}

void main()  // 主函数
{
    LED = 1;  // LED初始熄灭

    定时器0初始化();  // 初始化定时器0
    // 配置定时器参数和中断

    while(1)  // 无限循环
    {
        if(按键状态 == 1)  // 检测按键状态
        {
            LED = ~LED;  // LED状态取反
            // 切换LED开关状态

            按键状态 = 0;  // 清零按键状态
            // 避免重复触发
        }
    }
}
