### 3.3 矩阵键盘扫描

#### 3.3.1 硬件原理

矩阵键盘是一种高效的按键输入方式，具有以下特点：
- **行列结构**：4×4矩阵键盘需要8个I/O口
- **扫描方式**：逐行扫描，逐列检测
- **节省引脚**：相比独立按键节省大量I/O口

#### 3.3.2 4×4矩阵键盘扫描

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义矩阵键盘引脚
#define 键盘行 P1  // 定义键盘行端口
#define 键盘列 P2  // 定义键盘列端口

sbit LED = P3^0;  // 定义LED引脚

void 延时(unsigned int 延时时间);  // 延时函数声明

unsigned char 键盘扫描()  // 键盘扫描函数
{
    unsigned char 行, 列;  // 定义行列变量
    unsigned char 键值 = 0xFF;  // 键值变量，初始值0xFF表示无按键

    for(行 = 0; 行 < 4; 行++)  // 逐行扫描
    // 循环扫描4行
    {
        键盘行 = ~(0x01 << 行);  // 设置当前行为低电平
        // 0x01 << 行：将1左移行位
        // 例如：行=0时，0x01 << 0 = 0x01 = 00000001
        // ~：按位取反，00000001取反为11111110
        // 只有当前行为低电平，其他行为高电平

        延时(100);  // 延时消抖
        // 等待电平稳定

        for(列 = 0; 列 < 4; 列++)  // 逐列检测
        // 循环检测4列
        {
            if((键盘列 & (0x01 << 列)) == 0)  // 检测列状态
            // 键盘列 & (0x01 << 列)：检测当前列是否为低电平
            // 例如：列=0时，0x01 << 0 = 0x01 = 00000001
            // 键盘列 & 0x01：检测最低位是否为0
            {
                键值 = 行 * 4 + 列;  // 计算键值
                // 键值 = 行号 × 4 + 列号
                // 例如：行=0，列=0，键值=0
                // 行=0，列=1，键值=1

                while((键盘列 & (0x01 << 列)) == 0);  // 等待按键释放
                // 防止长按多次触发

                return 键值;  // 返回键值
                // 返回按下的按键编号
            }
        }
    }

    return 键值;  // 返回无按键
    // 0xFF表示没有按键按下
}

void main()  // 主函数
{
    unsigned char 按键值;  // 定义按键值变量

    LED = 1;  // LED初始熄灭

    while(1)  // 无限循环
    {
        按键值 = 键盘扫描();  // 调用键盘扫描函数

        if(按键值 != 0xFF)  // 检测是否有按键按下
        {
            LED = ~LED;  // LED状态取反
            // 根据按键值执行不同操作
        }
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

