unsigned char 键盘扫描()  // 键盘扫描函数定义
{
    unsigned char 行, 列;  // 定义行列变量
    // 行：表示当前扫描的行号(0-3)
    // 列：表示当前检测的列号(0-3)

    unsigned char 键值 = 0xFF;  // 定义键值变量
    // 0xFF = 11111111，表示没有按键按下
    // 键值范围：0-15，对应16个按键

    for(行 = 0; 行 < 4; 行++)  // 逐行扫描循环
    // 行从0开始，每次加1，直到3
    {
        键盘行 = ~(0x01 << 行);  // 设置当前行为低电平
        // 0x01 << 行：将1左移行位
        // 例如：行=0时，0x01 << 0 = 0x01 = 00000001
        // 行=1时，0x01 << 1 = 0x02 = 00000010
        // 行=2时，0x01 << 2 = 0x04 = 00000100
        // 行=3时，0x01 << 3 = 0x08 = 00001000

        // ~：按位取反运算符
        // 例如：~00000001 = 11111110
        // ~00000010 = 11111101
        // ~00000100 = 11111011
        // ~00001000 = 11110111

        // 键盘行 = ~(0x01 << 行)：设置当前行为低电平，其他行为高电平
        // 例如：行=0时，键盘行 = 11111110，P1.0为低电平
        // 行=1时，键盘行 = 11111101，P1.1为低电平

        延时(100);  // 调用延时函数消抖
        // 等待电平稳定，避免抖动干扰

        for(列 = 0; 列 < 4; 列++)  // 逐列检测循环
        // 列从0开始，每次加1，直到3
        {
            if((键盘列 & (0x01 << 列)) == 0)  // 检测列状态
            // 键盘列 & (0x01 << 列)：检测当前列是否为低电平
            // 例如：列=0时，0x01 << 0 = 0x01 = 00000001
            // 键盘列 & 0x01：检测最低位是否为0

            // == 0：判断结果是否为0
            // 如果结果为0，表示当前列为低电平，有按键按下

            {
                键值 = 行 * 4 + 列;  // 计算键值
                // 键值 = 行号 × 4 + 列号
                // 例如：行=0，列=0，键值=0×4+0=0
                // 行=0，列=1，键值=0×4+1=1
                // 行=1，列=0，键值=1×4+0=4
                // 行=3，列=3，键值=3×4+3=15

                while((键盘列 & (0x01 << 列)) == 0);  // 等待按键释放
                // 持续检测按键状态，直到按键释放
                // 防止长按多次触发

                return 键值;  // 返回键值
                // 返回按下的按键编号(0-15)
            }
        }
    }

    return 键值;  // 返回无按键
    // 0xFF表示没有按键按下
}

