                P1 = 0xF7;  // 点亮LED4
                // 0xF7 = 11110111，P1.3为低电平

                while(按键4 == 0);  // 等待按键4释放
            }
        }
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
