## 四、定时器应用

### 4.1 定时器基础应用

#### 4.1.1 定时器原理

51单片机有2个16位定时器/计数器(T0和T1)，具有以下特点：
- **工作模式**：4种工作模式(0-3)
- **定时功能**：基于机器周期定时
- **计数功能**：对外部脉冲计数
- **中断功能**：定时器溢出产生中断

#### 4.1.2 定时器0模式1

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED = P1^0;  // 定义LED引脚

unsigned char 计数器 = 0;  // 定义计数器变量

void 定时器0初始化()  // 定时器0初始化函数
{
    TMOD = 0x01;  // 设置定时器0为模式1
    // TMOD是定时器模式寄存器
    // 0x01 = 00000001
    // 低4位控制定时器0，高4位控制定时器1
    // 定时器0设置为模式1(16位定时器)
    // 定时器1保持不变

    TH0 = 0xFC;  // 设置定时器0高8位初值
    // TH0是定时器0高8位寄存器
    // 0xFC = 11111100
    // 定时器初值决定定时时间

    TL0 = 0x18;  // 设置定时器0低8位初值
    // TL0是定时器0低8位寄存器
    // 0x18 = 00011000
    // 定时时间约为1ms(假设晶振12MHz)

    TR0 = 1;  // 启动定时器0
    // TR0是定时器0运行控制位
    // 1表示启动定时器0，0表示停止定时器0

    ET0 = 1;  // 允许定时器0中断
    // ET0是定时器0中断允许位
    // 1表示允许定时器0中断，0表示禁止定时器0中断

    EA = 1;  // 开启总中断
    // EA是总中断允许位
    // 1表示开启总中断，0表示关闭总中断
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0xFC;  // 重新加载定时器初值
    // 定时器中断后需要重新设置初值
    // 保持定时时间一致

    TL0 = 0x18;  // 重新加载定时器初值
    // 定时器初值必须重新设置

    计数器++;  // 计数器加1
    // 每次中断计数器加1

    if(计数器 >= 500)  // 判断计数器是否达到500
    // 500次中断 = 500ms
    {
        计数器 = 0;  // 清零计数器
        // 重新开始计数

        LED = ~LED;  // LED状态取反
        // 每500ms切换一次LED状态
        // 实现LED闪烁，周期为1秒
    }
}

void main()  // 主函数
{
    LED = 1;  // LED初始熄灭

    定时器0初始化();  // 初始化定时器0
    // 配置定时器参数和中断

    while(1)  // 无限循环
    {
        // 主循环可以执行其他任务
        // 定时器中断独立运行
    }
}
```

#### 4.1.3 代码详解

```c
#include <reg52.h>  // 包含51单片机头文件，定义特殊功能寄存器

sbit LED = P1^0;  // 定义LED引脚为P1.0
// 用于显示定时器中断效果

unsigned char 计数器 = 0;  // 定义计数器变量，初始值为0
// 用于记录定时器中断次数
// unsigned char是无符号字符型，范围0-255

void 定时器0初始化()  // 定时器0初始化函数定义
{
    TMOD = 0x01;  // 设置定时器模式寄存器
    // TMOD是定时器模式寄存器，地址0x89
    // 0x01 = 00000001
    // 低4位控制定时器0，高4位控制定时器1
    // 定时器0：0001 = 模式1(16位定时器)
    // 定时器1：0000 = 保持不变

    TH0 = 0xFC;  // 设置定时器0高8位初值
    // TH0是定时器0高8位寄存器，地址0x8C
    // 0xFC = 11111100
    // 定时器初值计算：(65536 - 定时时间) / 256
    // 例如：1ms定时，初值 = 65536 - 1000 = 64536
    // 高8位 = 64536 / 256 = 252 = 0xFC

    TL0 = 0x18;  // 设置定时器0低8位初值
    // TL0是定时器0低8位寄存器，地址0x8A
    // 0x18 = 00011000
    // 低8位 = 64536 % 256 = 24 = 0x18
    // 定时时间 = (65536 - 初值) × 机器周期
    // 假设晶振12MHz，机器周期 = 1μs
    // 定时时间 = (65536 - 64536) × 1μs = 1000μs = 1ms

    TR0 = 1;  // 启动定时器0
    // TR0是定时器0运行控制位，TCON.4
    // 1表示启动定时器0，0表示停止定时器0
    // 定时器开始计数

    ET0 = 1;  // 允许定时器0中断
    // ET0是定时器0中断允许位，IE.1
    // 1表示允许定时器0中断，0表示禁止定时器0中断
    // 定时器溢出时会产生中断

    EA = 1;  // 开启总中断
    // EA是总中断允许位，IE.7
    // 1表示开启总中断，0表示关闭总中断
    // 只有开启总中断，各个中断才能生效
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0xFC;  // 重新加载定时器初值
    // 定时器模式1需要手动重新加载初值
    // 模式2可以自动重装初值

    TL0 = 0x18;  // 重新加载定时器初值
    // 必须重新设置初值，保持定时时间一致

    计数器++;  // 计数器加1
    // 每次中断计数器加1
    // 用于实现更长时间的定时

    if(计数器 >= 500)  // 判断计数器是否达到500
    // 500次中断 = 500ms
    // 每次中断1ms，500次 = 500ms
    {
        计数器 = 0;  // 清零计数器
        // 重新开始计数，准备下一个周期

        LED = ~LED;  // LED状态取反
        // 每500ms切换一次LED状态
        // LED亮500ms，灭500ms
        // 实现LED闪烁，周期为1秒
    }
}

void main()  // 主函数，程序入口
{
    LED = 1;  // 设置LED初始状态为熄灭
    // 输出高电平，共阳极LED熄灭

    定时器0初始化();  // 调用定时器0初始化函数
    // 配置定时器参数和中断

    while(1)  // 无限循环
    {
        // 主循环可以执行其他任务
        // 定时器中断独立运行
        // 不影响主程序的执行
    }
}
```

### 4.2 定时器中断

#### 4.2.1 中断优先级

51单片机有5个中断源，具有2个优先级：
- **外部中断0**：INT0，优先级最高
- **定时器0中断**：TF0
- **外部中断1**：INT1
- **定时器1中断**：TF1
- **串口中断**：RI/TI

#### 4.2.2 多定时器应用

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED1 = P1^0;  // 定义LED1引脚
sbit LED2 = P1^1;  // 定义LED2引脚

unsigned char 计数器1 = 0;  // 定时器0计数器
unsigned char 计数器2 = 0;  // 定时器1计数器

void 定时器初始化()  // 定时器初始化函数
{
    TMOD = 0x11;  // 设置定时器0和定时器1为模式1
    // 0x11 = 00010001
    // 定时器0：0001 = 模式1(16位定时器)
    // 定时器1：0001 = 模式1(16位定时器)

    // 定时器0初值，定时1ms
    TH0 = 0xFC;  // 定时器0高8位
    TL0 = 0x18;  // 定时器0低8位

    // 定时器1初值，定时2ms
    TH1 = 0xF8;  // 定时器1高8位
    TL1 = 0x30;  // 定时器1低8位

    TR0 = 1;  // 启动定时器0
    TR1 = 1;  // 启动定时器1

    ET0 = 1;  // 允许定时器0中断
    ET1 = 1;  // 允许定时器1中断

    EA = 1;  // 开启总中断
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0xFC;  // 重新加载定时器0初值
    TL0 = 0x18;  // 重新加载定时器0初值

    计数器1++;  // 定时器0计数器加1

    if(计数器1 >= 500)  // 500ms
    {
        计数器1 = 0;  // 清零计数器
        LED1 = ~LED1;  // LED1状态取反
    }
}

void 定时器1中断() interrupt 3  // 定时器1中断服务函数
{
    TH1 = 0xF8;  // 重新加载定时器1初值
    TL1 = 0x30;  // 重新加载定时器1初值

    计数器2++;  // 定时器1计数器加1

    if(计数器2 >= 250)  // 500ms
    {
        计数器2 = 0;  // 清零计数器
        LED2 = ~LED2;  // LED2状态取反
    }
}

void main()  // 主函数
{
    LED1 = 1;  // LED1初始熄灭
    LED2 = 1;  // LED2初始熄灭

    定时器初始化();  // 初始化定时器

    while(1)  // 无限循环
    {
        // 主循环
    }
}
```

