unsigned char PWM计数器 = 0;  // PWM计数器

void 定时器0初始化()  // 定时器0初始化函数
{
    TMOD = 0x01;  // 设置定时器0为模式1
    // 16位定时器

    TH0 = 0xFC;  // 设置定时器初值
    TL0 = 0x18;  // 定时1ms

    TR0 = 1;  // 启动定时器0
    ET0 = 1;  // 允许定时器0中断
    EA = 1;  // 开启总中断
}

