{
    TH0 = 0xFC;  // 重新加载定时器初值
    TL0 = 0x18;  // 重新加载定时器初值

    PWM计数器++;  // PWM计数器加1

    if(PWM计数器 <= 占空比)  // 高电平期间
    {
