### 4.4 精确延时

#### 4.4.1 定时器精确延时

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED = P1^0;  // 定义LED引脚

unsigned char 延时标志 = 0;  // 延时标志变量

void 定时器0初始化()  // 定时器0初始化函数
{
    TMOD = 0x01;  // 设置定时器0为模式1
    TH0 = 0xFC;  // 设置定时器初值
    TL0 = 0x18;  // 定时1ms

    TR0 = 1;  // 启动定时器0
    ET0 = 1;  // 允许定时器0中断
    EA = 1;  // 开启总中断
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0xFC;  // 重新加载定时器初值
    TL0 = 0x18;  // 重新加载定时器初值

    延时标志 = 1;  // 设置延时标志
    // 表示1ms延时完成
}

void 精确延时(unsigned int 毫秒数)  // 精确延时函数
{
    unsigned int 计数器;  // 定义计数器变量

    for(计数器 = 0; 计数器 < 毫秒数; 计数器++)  // 循环毫秒数
    {
        延时标志 = 0;  // 清零延时标志

        while(延时标志 == 0);  // 等待延时标志
        // 等待定时器中断设置标志
        // 实现精确的毫秒级延时
    }
}

void main()  // 主函数
{
    LED = 1;  // LED初始熄灭

    定时器0初始化();  // 初始化定时器0

    while(1)  // 无限循环
    {
        LED = 0;  // LED点亮
        精确延时(500);  // 精确延时500ms
        // 调用精确延时函数

        LED = 1;  // LED熄灭
        精确延时(500);  // 精确延时500ms
        // 实现精确的1秒周期闪烁
    }
}
