## 五、中断系统

### 5.1 外部中断配置

#### 5.1.1 外部中断原理

51单片机有2个外部中断(INT0和INT1)，具有以下特点：
- **触发方式**：边沿触发或电平触发
- **优先级**：INT0优先级高于INT1
- **中断向量**：INT0为0，INT1为2
- **引脚定义**：INT0为P3.2，INT1为P3.3

#### 5.1.2 外部中断0配置

```c
#include <reg52.h>  // 包含51单片机头文件

sbit 外部中断引脚 = P3^2;  // 定义外部中断0引脚
sbit LED = P1^0;  // 定义LED引脚

void 外部中断0初始化()  // 外部中断0初始化函数
{
    IT0 = 1;  // 设置外部中断0为下降沿触发
    // IT0是外部中断0触发方式选择位
    // 1表示下降沿触发，0表示低电平触发

    EX0 = 1;  // 允许外部中断0
    // EX0是外部中断0允许位
    // 1表示允许外部中断0，0表示禁止外部中断0

    EA = 1;  // 开启总中断
    // EA是总中断允许位
    // 1表示开启总中断，0表示关闭总中断
}

void 外部中断0中断() interrupt 0  // 外部中断0中断服务函数
{
    LED = ~LED;  // LED状态取反
    // 外部中断触发时切换LED状态
}

void main()  // 主函数
{
    LED = 1;  // LED初始熄灭

    外部中断0初始化();  // 初始化外部中断0
    // 配置外部中断参数

    while(1)  // 无限循环
    {
        // 主循环可以执行其他任务
        // 外部中断独立运行
    }
}
```

#### 5.1.3 代码详解

```c
#include <reg52.h>  // 包含51单片机头文件，定义特殊功能寄存器

sbit 外部中断引脚 = P3^2;  // 定义外部中断0引脚为P3.2
// INT0连接到P3.2引脚
// 用于触发外部中断

sbit LED = P1^0;  // 定义LED引脚为P1.0
// 用于显示外部中断触发状态

void 外部中断0初始化()  // 外部中断0初始化函数定义
{
    IT0 = 1;  // 设置外部中断0触发方式
    // IT0是外部中断0触发方式选择位，TCON.0
    // 1表示下降沿触发（高电平到低电平的跳变）
    // 0表示低电平触发（持续低电平）
    // 下降沿触发更适合按键等应用

    EX0 = 1;  // 允许外部中断0
    // EX0是外部中断0允许位，IE.0
    // 1表示允许外部中断0，0表示禁止外部中断0
    // 只有设置EX0=1，外部中断0才能生效

    EA = 1;  // 开启总中断
    // EA是总中断允许位，IE.7
    // 1表示开启总中断，0表示关闭总中断
    // 只有开启总中断，各个中断才能生效
}

void 外部中断0中断() interrupt 0  // 外部中断0中断服务函数
{
    LED = ~LED;  // LED状态取反
    // 外部中断触发时切换LED状态
    // 每次外部中断触发，LED状态切换一次
    // interrupt 0表示这是外部中断0的中断服务函数
    // 中断向量号为0
}

void main()  // 主函数，程序入口
{
    LED = 1;  // 设置LED初始状态为熄灭
    // 输出高电平，共阳极LED熄灭

    外部中断0初始化();  // 调用外部中断0初始化函数
    // 配置外部中断参数

    while(1)  // 无限循环
    {
        // 主循环可以执行其他任务
        // 外部中断独立运行
        // 当P3.2引脚出现下降沿时，会触发外部中断0
        // CPU会暂停当前程序，执行外部中断0中断服务函数
        // 中断服务函数执行完毕后，返回主程序继续执行
    }
}
```

### 5.2 中断优先级

#### 5.2.1 优先级设置

51单片机有2个中断优先级，可以通过IP寄存器设置：
- **默认优先级**：按中断向量号排序
- **高优先级**：可以打断低优先级中断
- **低优先级**：不能打断高优先级中断

#### 5.2.2 多中断应用

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED1 = P1^0;  // 定义LED1引脚
sbit LED2 = P1^1;  // 定义LED2引脚

unsigned char 计数器0 = 0;  // 定时器0计数器
unsigned char 计数器1 = 0;  // 定时器1计数器

void 中断系统初始化()  // 中断系统初始化函数
{
    TMOD = 0x11;  // 设置定时器0和定时器1为模式1
    // 0x11 = 00010001
    // 定时器0：模式1(16位定时器)
    // 定时器1：模式1(16位定时器)

    // 定时器0初值，定时1ms
    TH0 = 0xFC;  // 定时器0高8位
    TL0 = 0x18;  // 定时器0低8位

    // 定时器1初值，定时2ms
    TH1 = 0xF8;  // 定时器1高8位
    TL1 = 0x30;  // 定时器1低8位

    // 外部中断0配置
    IT0 = 1;  // 外部中断0下降沿触发
    EX0 = 1;  // 允许外部中断0

    // 定时器配置
    TR0 = 1;  // 启动定时器0
    TR1 = 1;  // 启动定时器1

    // 中断允许
    ET0 = 1;  // 允许定时器0中断
    ET1 = 1;  // 允许定时器1中断

    // 优先级设置
    PT0 = 1;  // 定时器0高优先级
    // PT0是定时器0优先级位，IP.1
    // 1表示高优先级，0表示低优先级

    PT1 = 0;  // 定时器1低优先级
    // PT1是定时器1优先级位，IP.3
    // 1表示高优先级，0表示低优先级

    EA = 1;  // 开启总中断
}

void 外部中断0中断() interrupt 0  // 外部中断0中断服务函数
{
    LED1 = ~LED1;  // LED1状态取反
    // 外部中断触发时切换LED1状态
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0xFC;  // 重新加载定时器0初值
    TL0 = 0x18;  // 重新加载定时器0初值

    计数器0++;  // 定时器0计数器加1

    if(计数器0 >= 500)  // 500ms
    {
        计数器0 = 0;  // 清零计数器
        LED2 = ~LED2;  // LED2状态取反
    }
}

void 定时器1中断() interrupt 3  // 定时器1中断服务函数
{
    TH1 = 0xF8;  // 重新加载定时器1初值
    TL1 = 0x30;  // 重新加载定时器1初值

    计数器1++;  // 定时器1计数器加1

    if(计数器1 >= 250)  // 500ms
    {
        计数器1 = 0;  // 清零计数器
    }
}

void main()  // 主函数
{
    LED1 = 1;  // LED1初始熄灭
    LED2 = 1;  // LED2初始熄灭

    中断系统初始化();  // 初始化中断系统

    while(1)  // 无限循环
    {
        // 主循环
    }
}
```

### 5.3 中断嵌套

#### 5.3.1 中断嵌套原理

中断嵌套是指高优先级中断可以打断低优先级中断的执行：
- **嵌套条件**：高优先级中断请求
- **嵌套限制**：最多2级嵌套
- **返回机制**：中断服务函数执行完毕后返回

#### 5.3.2 中断嵌套示例

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED1 = P1^0;  // 定义LED1引脚
sbit LED2 = P1^1;  // 定义LED2引脚
sbit LED3 = P1^2;  // 定义LED3引脚

unsigned char 计数器0 = 0;  // 定时器0计数器
unsigned char 计数器1 = 0;  // 定时器1计数器

void 中断系统初始化()  // 中断系统初始化函数
{
    TMOD = 0x11;  // 设置定时器0和定时器1为模式1

    // 定时器0初值，定时1ms
    TH0 = 0xFC;  // 定时器0高8位
    TL0 = 0x18;  // 定时器0低8位

    // 定时器1初值，定时2ms
    TH1 = 0xF8;  // 定时器1高8位
    TL1 = 0x30;  // 定时器1低8位

    // 定时器配置
    TR0 = 1;  // 启动定时器0
    TR1 = 1;  // 启动定时器1

    // 中断允许
    ET0 = 1;  // 允许定时器0中断
    ET1 = 1;  // 允许定时器1中断

    // 优先级设置
    PT0 = 1;  // 定时器0高优先级
    PT1 = 0;  // 定时器1低优先级

    EA = 1;  // 开启总中断
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0xFC;  // 重新加载定时器0初值
    TL0 = 0x18;  // 重新加载定时器0初值

    LED1 = 0;  // LED1点亮
    // 进入定时器0中断

    计数器0++;  // 定时器0计数器加1

    if(计数器0 >= 500)  // 500ms
    {
        计数器0 = 0;  // 清零计数器
        LED2 = ~LED2;  // LED2状态取反
    }

    LED1 = 1;  // LED1熄灭
    // 退出定时器0中断
}

void 定时器1中断() interrupt 3  // 定时器1中断服务函数
{
    TH1 = 0xF8;  // 重新加载定时器1初值
    TL1 = 0x30;  // 重新加载定时器1初值

    LED3 = 0;  // LED3点亮
    // 进入定时器1中断

    计数器1++;  // 定时器1计数器加1

    if(计数器1 >= 250)  // 500ms
    {
        计数器1 = 0;  // 清零计数器
    }

    LED3 = 1;  // LED3熄灭
    // 退出定时器1中断
}

void main()  // 主函数
{
    LED1 = 1;  // LED1初始熄灭
    LED2 = 1;  // LED2初始熄灭
    LED3 = 1;  // LED3初始熄灭

    中断系统初始化();  // 初始化中断系统

    while(1)  // 无限循环
    {
        // 主循环
        // 定时器0中断可以打断定时器1中断
        // 因为定时器0是高优先级
    }
}
```

