#### 5.4.2 频率测量

```c
#include <reg52.h>  // 包含51单片机头文件

sbit 信号输入 = P3^2;  // 定义信号输入引脚，连接外部中断0

unsigned int 脉冲计数 = 0;  // 脉冲计数变量
unsigned int 频率值 = 0;  // 频率值变量

void 外部中断0初始化()  // 外部中断0初始化函数
{
    IT0 = 1;  // 设置外部中断0为下降沿触发
    EX0 = 1;  // 允许外部中断0
    EA = 1;  // 开启总中断
}

void 定时器0初始化()  // 定时器0初始化函数
{
    TMOD = 0x01;  // 设置定时器0为模式1
    TH0 = 0x3C;  // 设置定时器初值
    TL0 = 0xB0;  // 定时50ms

    TR0 = 1;  // 启动定时器0
    ET0 = 1;  // 允许定时器0中断
}

void 外部中断0中断() interrupt 0  // 外部中断0中断服务函数
{
    脉冲计数++;  // 脉冲计数加1
    // 每次外部中断触发，表示检测到一个脉冲
}

void 定时器0中断() interrupt 1  // 定时器0中断服务函数
{
    TH0 = 0x3C;  // 重新加载定时器初值
    TL0 = 0xB0;  // 重新加载定时器初值

    频率值 = 脉冲计数 * 20;  // 计算频率值
    // 频率 = 脉冲计数 / 时间
    // 时间 = 50ms = 0.05s
    // 频率 = 脉冲计数 / 0.05 = 脉冲计数 * 20

    脉冲计数 = 0;  // 清零脉冲计数
    // 重新开始计数

    P2 = 频率值 / 256;  // 显示频率值高8位
    P1 = 频率值 % 256;  // 显示频率值低8位
    // 将频率值显示到端口
}

void main()  // 主函数
{
    脉冲计数 = 0;  // 初始化脉冲计数
    频率值 = 0;  // 初始化频率值

    外部中断0初始化();  // 初始化外部中断0
    定时器0初始化();  // 初始化定时器0

    while(1)  // 无限循环
    {
        // 主循环
        // 频率测量在中断中处理
    }
}
