## 六、串口通信

### 6.1 串口初始化配置

#### 6.1.1 串口原理

51单片机有一个全双工串行接口，具有以下特点：
- **通信模式**：4种工作模式(0-3)
- **波特率**：可配置的通信速率
- **数据格式**：8位或9位数据
- **中断功能**：发送和接收中断

#### 6.1.2 串口初始化

```c
#include <reg52.h>  // 包含51单片机头文件

void 串口初始化()  // 串口初始化函数
{
    SCON = 0x50;  // 设置串口为模式1，允许接收
    // SCON是串口控制寄存器
    // 0x50 = 01010000
    // SM0 = 0, SM1 = 1：模式1(8位UART，波特率可变)
    // SM2 = 0：多机通信控制位
    // REN = 1：允许接收
    // TB8 = 0：发送数据第9位
    // RB8 = 0：接收数据第9位
    // TI = 0：发送中断标志
    // RI = 0：接收中断标志

    TMOD = 0x20;  // 设置定时器1为模式2
    // 0x20 = 00100000
    // 定时器1：模式2(8位自动重装)
    // 定时器0：保持不变

    TH1 = 0xFD;  // 设置定时器1初值，波特率9600
    // 0xFD = 11111101
    // 波特率计算：Baud = (2^SMOD / 32) × (Fosc / (12 × (256 - TH1)))
    // 假设晶振11.0592MHz，SMOD=0
    // 9600 = (1 / 32) × (11059200 / (12 × (256 - 253)))
    // 9600 = (1 / 32) × (11059200 / 36)
    // 9600 = 9600

    TL1 = 0xFD;  // 设置定时器1初值
    // 模式2自动重装，TL1自动从TH1重装

    TR1 = 1;  // 启动定时器1
    // TR1是定时器1运行控制位

    ES = 1;  // 允许串口中断
    // ES是串口中断允许位

    EA = 1;  // 开启总中断
    // EA是总中断允许位
}

void main()  // 主函数
{
    串口初始化();  // 初始化串口
    // 配置串口参数

    while(1)  // 无限循环
    {
        // 主循环
    }
}
```

#### 6.1.3 代码详解

```c
#include <reg52.h>  // 包含51单片机头文件，定义特殊功能寄存器

void 串口初始化()  // 串口初始化函数定义
{
    SCON = 0x50;  // 设置串口控制寄存器
    // SCON是串口控制寄存器，地址0x98
    // 0x50 = 01010000
    // SM0(SCON.7) = 0：串口模式选择位0
    // SM1(SCON.6) = 1：串口模式选择位1
    // SM0=0, SM1=1：模式1(8位UART，波特率可变)
    // SM2(SCON.5) = 0：多机通信控制位
    // REN(SCON.4) = 1：接收允许位
    // TB8(SCON.3) = 0：发送数据第9位
    // RB8(SCON.2) = 0：接收数据第9位
    // TI(SCON.1) = 0：发送中断标志位
    // RI(SCON.0) = 0：接收中断标志位

    TMOD = 0x20;  // 设置定时器模式寄存器
    // TMOD是定时器模式寄存器，地址0x89
    // 0x20 = 00100000
    // 定时器1：0010 = 模式2(8位自动重装)
    // 定时器0：0000 = 保持不变

    TH1 = 0xFD;  // 设置定时器1高8位初值
    // TH1是定时器1高8位寄存器，地址0x8D
    // 0xFD = 11111101 = 253
    // 波特率计算：Baud = (2^SMOD / 32) × (Fosc / (12 × (256 - TH1)))
    // 假设晶振11.0592MHz，SMOD=0(PCON.7)
    // 9600 = (1 / 32) × (11059200 / (12 × (256 - 253)))
    // 9600 = (1 / 32) × (11059200 / 36)
    // 9600 = (1 / 32) × 307200
    // 9600 = 9600

    TL1 = 0xFD;  // 设置定时器1低8位初值
    // TL1是定时器1低8位寄存器，地址0x8B
    // 模式2是8位自动重装模式
    // TL1溢出后自动从TH1重装初值

    TR1 = 1;  // 启动定时器1
    // TR1是定时器1运行控制位，TCON.6
    // 1表示启动定时器1，0表示停止定时器1
    // 定时器1作为波特率发生器

    ES = 1;  // 允许串口中断
    // ES是串口中断允许位，IE.4
    // 1表示允许串口中断，0表示禁止串口中断
    // 发送或接收完成时会产生中断

    EA = 1;  // 开启总中断
    // EA是总中断允许位，IE.7
    // 1表示开启总中断，0表示关闭总中断
    // 只有开启总中断，各个中断才能生效
}

void main()  // 主函数，程序入口
{
    串口初始化();  // 调用串口初始化函数
    // 配置串口参数：模式1，波特率9600

    while(1)  // 无限循环
    {
        // 主循环可以执行其他任务
        // 串口通信在中断中处理
    }
}
```

### 6.2 数据发送接收

#### 6.2.1 串口发送数据

```c
#include <reg52.h>  // 包含51单片机头文件

void 串口初始化()  // 串口初始化函数
{
    SCON = 0x50;  // 设置串口为模式1，允许接收
    TMOD = 0x20;  // 设置定时器1为模式2
    TH1 = 0xFD;  // 设置定时器1初值，波特率9600
    TL1 = 0xFD;  // 设置定时器1初值
    TR1 = 1;  // 启动定时器1
}

void 串口发送字符(unsigned char 字符)  // 串口发送字符函数
{
    SBUF = 字符;  // 将字符写入串口缓冲区
    // SBUF是串口数据缓冲寄存器
    // 写入SBUF后开始发送数据

    while(TI == 0);  // 等待发送完成
    // TI是发送中断标志位
    // TI=1表示发送完成

    TI = 0;  // 清零发送中断标志
    // 需要软件清零TI标志
}

void main()  // 主函数
{
    unsigned char 发送数据 = 'A';  // 定义发送数据变量

    串口初始化();  // 初始化串口

    while(1)  // 无限循环
    {
        串口发送字符(发送数据);  // 发送字符
        // 调用串口发送字符函数

        发送数据++;  // 发送数据加1
        // 发送下一个字符

        if(发送数据 > 'Z')  // 判断是否超过'Z'
        {
            发送数据 = 'A';  // 重新从'A'开始
        }
    }
}
```

#### 6.2.2 串口接收数据

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED = P1^0;  // 定义LED引脚

void 串口初始化()  // 串口初始化函数
{
    SCON = 0x50;  // 设置串口为模式1，允许接收
    TMOD = 0x20;  // 设置定时器1为模式2
    TH1 = 0xFD;  // 设置定时器1初值，波特率9600
    TL1 = 0xFD;  // 设置定时器1初值
    TR1 = 1;  // 启动定时器1
    ES = 1;  // 允许串口中断
    EA = 1;  // 开启总中断
}

void 串口中断() interrupt 4  // 串口中断服务函数
{
    if(RI == 1)  // 判断是否接收中断
    {
        RI = 0;  // 清零接收中断标志
        // 需要软件清零RI标志

        if(SBUF == 'A')  // 判断接收到的字符
        {
            LED = 0;  // LED点亮
            // 接收到'A'时点亮LED
        }
        else if(SBUF == 'B')  // 判断接收到的字符
        {
            LED = 1;  // LED熄灭
            // 接收到'B'时熄灭LED
        }
    }

    if(TI == 1)  // 判断是否发送中断
    {
        TI = 0;  // 清零发送中断标志
        // 需要软件清零TI标志
    }
}

void main()  // 主函数
{
    LED = 1;  // LED初始熄灭

    串口初始化();  // 初始化串口

    while(1)  // 无限循环
    {
        // 主循环
        // 串口接收在中断中处理
    }
}
```

### 6.3 串口中断通信

#### 6.3.1 串口中断发送接收

```c
#include <reg52.h>  // 包含51单片机头文件

unsigned char 接收缓冲区[32];  // 接收缓冲区
unsigned char 接收索引 = 0;  // 接收索引

void 串口初始化()  // 串口初始化函数
{
    SCON = 0x50;  // 设置串口为模式1，允许接收
    TMOD = 0x20;  // 设置定时器1为模式2
    TH1 = 0xFD;  // 设置定时器1初值，波特率9600
    TL1 = 0xFD;  // 设置定时器1初值
    TR1 = 1;  // 启动定时器1
    ES = 1;  // 允许串口中断
    EA = 1;  // 开启总中断
}

void 串口发送字符(unsigned char 字符)  // 串口发送字符函数
{
    SBUF = 字符;  // 将字符写入串口缓冲区

    while(TI == 0);  // 等待发送完成
    TI = 0;  // 清零发送中断标志
}

void 串口发送字符串(unsigned char *字符串)  // 串口发送字符串函数
{
    while(*字符串 != '\0')  // 循环直到字符串结束
    {
        串口发送字符(*字符串);  // 发送字符
        字符串++;  // 指针加1，指向下一个字符
    }
}

void 串口中断() interrupt 4  // 串口中断服务函数
{
    if(RI == 1)  // 判断是否接收中断
    {
        RI = 0;  // 清零接收中断标志

        接收缓冲区[接收索引] = SBUF;  // 保存接收到的数据
        // 将接收到的数据保存到缓冲区

        接收索引++;  // 接收索引加1

        if(接收索引 >= 32)  // 判断缓冲区是否满
        {
            接收索引 = 0;  // 重新开始接收
        }
    }

    if(TI == 1)  // 判断是否发送中断
    {
        TI = 0;  // 清零发送中断标志
    }
}

void main()  // 主函数
{
    串口初始化();  // 初始化串口

    串口发送字符串("Hello World!\r\n");  // 发送字符串
    // 发送欢迎信息

    while(1)  // 无限循环
    {
        // 主循环
        // 串口通信在中断中处理
    }
}
