#### 6.3.2 串口命令处理

```c
#include <reg52.h>  // 包含51单片机头文件

sbit LED1 = P1^0;  // 定义LED1引脚
sbit LED2 = P1^1;  // 定义LED2引脚

unsigned char 接收缓冲区[32];  // 接收缓冲区
unsigned char 接收索引 = 0;  // 接收索引

void 串口初始化()  // 串口初始化函数
{
    SCON = 0x50;  // 设置串口为模式1，允许接收
    TMOD = 0x20;  // 设置定时器1为模式2
    TH1 = 0xFD;  // 设置定时器1初值，波特率9600
    TL1 = 0xFD;  // 设置定时器1初值
    TR1 = 1;  // 启动定时器1
    ES = 1;  // 允许串口中断
    EA = 1;  // 开启总中断
}

void 串口发送字符(unsigned char 字符)  // 串口发送字符函数
{
    SBUF = 字符;  // 将字符写入串口缓冲区

    while(TI == 0);  // 等待发送完成
    TI = 0;  // 清零发送中断标志
}

void 串口发送字符串(unsigned char *字符串)  // 串口发送字符串函数
{
    while(*字符串 != '\0')  // 循环直到字符串结束
    {
        串口发送字符(*字符串);  // 发送字符
        字符串++;  // 指针加1
    }
}

void 处理命令()  // 处理命令函数
{
    if(接收缓冲区[0] == 'L' && 接收缓冲区[1] == 'E' && 接收缓冲区[2] == 'D')  // 判断LED命令
    {
        if(接收缓冲区[3] == '1' && 接收缓冲区[4] == 'O' && 接收缓冲区[5] == 'N')  // LED1 ON
        {
            LED1 = 0;  // LED1点亮
            串口发送字符串("LED1 ON\r\n");  // 发送响应
        }
        else if(接收缓冲区[3] == '1' && 接收缓冲区[4] == 'O' && 接收缓冲区[5] == 'F' && 接收缓冲区[6] == 'F')  // LED1 OFF
        {
            LED1 = 1;  // LED1熄灭
            串口发送字符串("LED1 OFF\r\n");  // 发送响应
        }
        else if(接收缓冲区[3] == '2' && 接收缓冲区[4] == 'O' && 接收缓冲区[5] == 'N')  // LED2 ON
        {
            LED2 = 0;  // LED2点亮
            串口发送字符串("LED2 ON\r\n");  // 发送响应
        }
        else if(接收缓冲区[3] == '2' && 接收缓冲区[4] == 'O' && 接收缓冲区[5] == 'F' && 接收缓冲区[6] == 'F')  // LED2 OFF
        {
            LED2 = 1;  // LED2熄灭
            串口发送字符串("LED2 OFF\r\n");  // 发送响应
        }
    }
}

void 串口中断() interrupt 4  // 串口中断服务函数
{
    if(RI == 1)  // 判断是否接收中断
    {
        RI = 0;  // 清零接收中断标志

        接收缓冲区[接收索引] = SBUF;  // 保存接收到的数据

        if(接收缓冲区[接收索引] == '\r')  // 判断是否接收到回车
        {
            接收缓冲区[接收索引] = '\0';  // 字符串结束符
            处理命令();  // 处理命令
            接收索引 = 0;  // 清零接收索引
        }
        else  // 未接收到回车
        {
            接收索引++;  // 接收索引加1

            if(接收索引 >= 32)  // 判断缓冲区是否满
            {
                接收索引 = 0;  // 重新开始接收
            }
        }
    }

    if(TI == 1)  // 判断是否发送中断
    {
        TI = 0;  // 清零发送中断标志
    }
}

void main()  // 主函数
{
    LED1 = 1;  // LED1初始熄灭
    LED2 = 1;  // LED2初始熄灭

    串口初始化();  // 初始化串口

    串口发送字符串("System Ready!\r\n");  // 发送欢迎信息
    串口发送字符串("Commands:\r\n");  // 发送命令提示
