    串口发送字符串("LED2ON - Turn on LED2\r\n");  // 发送命令提示
    串口发送字符串("LED2OFF - Turn off LED2\r\n");  // 发送命令提示

    while(1)  // 无限循环
    {
        // 主循环
        // 串口通信在中断中处理
    }
}
