## 七、显示模块

### 7.1 数码管静态显示

#### 7.1.1 数码管原理

数码管是一种半导体显示器件，具有以下特点：
- **显示方式**：共阳极或共阴极
- **显示内容**：数字0-9和部分字母
- **驱动方式**：静态驱动或动态扫描
- **段码控制**：7段+小数点

#### 7.1.2 数码管静态显示代码

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义数码管段码表（共阳极）
unsigned char 数码管段码[] = {
    0xC0,  // 0
    0xF9,  // 1
    0xA4,  // 2
    0xB0,  // 3
    0x99,  // 4
    0x92,  // 5
    0x82,  // 6
    0xF8,  // 7
    0x80,  // 8
    0x90   // 9
};

void 数码管显示(unsigned char 数字)  // 数码管显示函数
{
    P0 = 数码管段码[数字];  // 输出段码到P0端口
    // 根据数字选择对应的段码
    // 输出到数码管显示
}

void main()  // 主函数
{
    unsigned char 显示数字 = 0;  // 定义显示数字变量

    while(1)  // 无限循环
    {
        数码管显示(显示数字);  // 显示数字
        // 调用数码管显示函数

        显示数字++;  // 数字加1

        if(显示数字 > 9)  // 判断数字是否超过9
        {
            显示数字 = 0;  // 重新从0开始
        }
    }
}
```

### 7.2 数码管动态扫描

#### 7.2.1 动态扫描原理

动态扫描是一种节省I/O口的显示方式：
- **扫描原理**：快速轮流显示各位数码管
- **扫描频率**：通常为50-100Hz
- **视觉效果**：人眼看到的是同时显示
- **节省引脚**：相比静态显示节省大量I/O口

#### 7.2.2 4位数码管动态扫描

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义数码管段码表（共阳极）
unsigned char 数码管段码[] = {
    0xC0,  // 0
    0xF9,  // 1
    0xA4,  // 2
    0xB0,  // 3
    0x99,  // 4
    0x92,  // 5
    0x82,  // 6
    0xF8,  // 7
    0x80,  // 8
    0x90   // 9
};

// 定义数码管位选表
unsigned char 数码管位选[] = {
    0xFE,  // 第1位
    0xFD,  // 第2位
    0xFB,  // 第3位
    0xF7   // 第4位
};

unsigned char 显示数据[4] = {1, 2, 3, 4};  // 显示数据数组

void 延时(unsigned int 延时时间);  // 延时函数声明

void 数码管动态扫描()  // 数码管动态扫描函数
{
    unsigned char 位索引;  // 定义位索引变量

    for(位索引 = 0; 位索引 < 4; 位索引++)  // 循环扫描4位
    {
        P2 = 数码管位选[位索引];  // 选择当前位
        // 输出位选信号

        P0 = 数码管段码[显示数据[位索引]];  // 输出段码
        // 根据显示数据选择段码

        延时(1000);  // 延时消影
        // 避免数码管显示混乱

        P0 = 0xFF;  // 消隐
        // 关闭所有段，避免重影
    }
}

void main()  // 主函数
{
    while(1)  // 无限循环
    {
        数码管动态扫描();  // 动态扫描显示
        // 持续扫描显示
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

### 7.3 LCD1602显示

#### 7.3.1 LCD1602原理

LCD1602是一种字符型液晶显示模块，具有以下特点：
- **显示容量**：16×2字符
- **显示内容**：ASCII字符和自定义字符
- **接口方式**：并行接口
- **控制方式**：指令控制

#### 7.3.2 LCD1602初始化和显示

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义LCD1602引脚
sbit LCD_RS = P2^0;  // 寄存器选择
sbit LCD_RW = P2^1;  // 读写选择
sbit LCD_EN = P2^2;  // 使能信号

#define LCD_DATA P0  // LCD数据端口

void 延时(unsigned int 延时时间);  // 延时函数声明

void LCD写命令(unsigned char 命令)  // LCD写命令函数
{
    LCD_RS = 0;  // 选择命令寄存器
    // 0表示命令，1表示数据

    LCD_RW = 0;  // 选择写操作
    // 0表示写，1表示读

    LCD_DATA = 命令;  // 输出命令到数据端口

    LCD_EN = 1;  // 使能信号高电平
    // 产生下降沿锁存数据

    延时(100);  // 延时

    LCD_EN = 0;  // 使能信号低电平
    // 完成写操作
}

void LCD写数据(unsigned char 数据)  // LCD写数据函数
{
    LCD_RS = 1;  // 选择数据寄存器
    // 1表示数据，0表示命令

    LCD_RW = 0;  // 选择写操作
    // 0表示写，1表示读

    LCD_DATA = 数据;  // 输出数据到数据端口

    LCD_EN = 1;  // 使能信号高电平
    // 产生下降沿锁存数据

    延时(100);  // 延时

    LCD_EN = 0;  // 使能信号低电平
    // 完成写操作
}

void LCD初始化()  // LCD初始化函数
{
    延时(15000);  // 等待LCD上电稳定

    LCD写命令(0x38);  // 设置8位数据接口，两行显示
    // 0x38 = 00111000
    // DL=1: 8位数据接口
    // N=1: 两行显示
    // F=0: 5×7点阵

    LCD写命令(0x0C);  // 显示开，光标关，闪烁关
    // 0x0C = 00001100
    // D=1: 显示开
    // C=0: 光标关
    // B=0: 闪烁关

    LCD写命令(0x06);  // 文字不动，地址自动加1
    // 0x06 = 00000110
    // I/D=1: 地址自动加1
    // S=0: 文字不动

    LCD写命令(0x01);  // 清屏
    // 0x01 = 00000001
    // 清除所有显示内容

    延时(2000);  // 等待清屏完成
}

void LCD显示字符串(unsigned char 行, unsigned char 列, unsigned char *字符串)  // LCD显示字符串函数
{
    unsigned char 地址;  // 定义地址变量

    if(行 == 0)  // 判断行号
    {
        地址 = 0x80 + 列;  // 第一行地址
        // 0x80是第一行起始地址
    }
    else  // 第二行
    {
        地址 = 0xC0 + 列;  // 第二行地址
        // 0xC0是第二行起始地址
    }

    LCD写命令(地址);  // 设置显示地址
    // 设置光标位置

    while(*字符串 != '\0')  // 循环直到字符串结束
    {
        LCD写数据(*字符串);  // 写入字符
        字符串++;  // 指针加1
    }
}

void main()  // 主函数
{
    LCD初始化();  // 初始化LCD

    LCD显示字符串(0, 0, "Hello World!");  // 第一行显示
    LCD显示字符串(1, 0, "LCD1602 Test");  // 第二行显示

    while(1)  // 无限循环
    {
        // 主循环
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

### 7.4 OLED显示

#### 7.4.1 OLED原理

OLED（有机发光二极管）是一种新型显示技术，具有以下特点：
- **显示方式**：自发光，无需背光
- **显示效果**：高对比度，宽视角
- **功耗**：相比LCD更低
- **接口方式**：I2C或SPI接口

#### 7.4.2 OLED初始化和显示

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义OLED引脚
sbit OLED_SCL = P2^0;  // I2C时钟线
sbit OLED_SDA = P2^1;  // I2C数据线

void 延时(unsigned int 延时时间);  // 延时函数声明

void I2C起始()  // I2C起始信号
{
    OLED_SDA = 1;  // 数据线高电平
    OLED_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    OLED_SDA = 0;  // 数据线低电平
    延时(10);  // 延时
    OLED_SCL = 0;  // 时钟线低电平
}

void I2C停止()  // I2C停止信号
{
    OLED_SDA = 0;  // 数据线低电平
    OLED_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    OLED_SDA = 1;  // 数据线高电平
    延时(10);  // 延时
}

void I2C发送字节(unsigned char 字节)  // I2C发送字节
{
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环发送8位
    {
        if(字节 & 0x80)  // 判断最高位
        {
            OLED_SDA = 1;  // 数据线高电平
        }
        else  // 最高位为0
        {
            OLED_SDA = 0;  // 数据线低电平
        }

        OLED_SCL = 1;  // 时钟线高电平
        延时(10);  // 延时
        OLED_SCL = 0;  // 时钟线低电平
        延时(10);  // 延时

        字节 <<= 1;  // 字节左移1位
        // 准备发送下一位
    }

    OLED_SDA = 1;  // 数据线高电平
    OLED_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    OLED_SCL = 0;  // 时钟线低电平
}

void OLED写命令(unsigned char 命令)  // OLED写命令
{
    I2C起始();  // 发送起始信号
    I2C发送字节(0x78);  // 发送OLED地址
    I2C发送字节(0x00);  // 发送命令标志
    I2C发送字节(命令);  // 发送命令
    I2C停止();  // 发送停止信号
}

void OLED写数据(unsigned char 数据)  // OLED写数据
{
    I2C起始();  // 发送起始信号
    I2C发送字节(0x78);  // 发送OLED地址
    I2C发送字节(0x40);  // 发送数据标志
    I2C发送字节(数据);  // 发送数据
    I2C停止();  // 发送停止信号
}

void OLED初始化()  // OLED初始化
{
    延时(10000);  // 等待OLED上电稳定

    OLED写命令(0xAE);  // 关闭显示
    OLED写命令(0xD5);  // 设置时钟分频因子
    OLED写命令(0x80);  // 建议值
    OLED写命令(0xA8);  // 设置驱动路数
    OLED写命令(0x3F);  // 默认0X3F(1/64)
    OLED写命令(0xD3);  // 设置显示偏移
    OLED写命令(0x00);  // 默认为0
    OLED写命令(0x40);  // 设置显示开始行
    OLED写命令(0x8D);  // 电荷泵设置
    OLED写命令(0x14);  // 开启电荷泵
    OLED写命令(0x20);  // 设置内存地址模式
    OLED写命令(0x02);  // 页地址模式
    OLED写命令(0xA1);  // 段重定向设置
    OLED写命令(0xC8);  // 设置COM扫描方向
    OLED写命令(0xDA);  // 设置COM硬件引脚配置
    OLED写命令(0x12);  // 默认值
    OLED写命令(0x81);  // 对比度设置
    OLED写命令(0xCF);  // 默认值
    OLED写命令(0xD9);  // 设置预充电周期
    OLED写命令(0xF1);  // 默认值
    OLED写命令(0xDB);  // 设置VCOMH电压倍率
    OLED写命令(0x40);  // 默认值
    OLED写命令(0xA4);  // 全局显示开启
    OLED写命令(0xA6);  // 设置显示方式
    OLED写命令(0xAF);  // 开启显示
}

void OLED清屏()  // OLED清屏
{
    unsigned char 页, 列;  // 定义页和列变量

    for(页 = 0; 页 < 8; 页++)  // 循环8页
    {
        OLED写命令(0xB0 + 页);  // 设置页地址
        OLED写命令(0x00);  // 设置列地址低4位
        OLED写命令(0x10);  // 设置列地址高4位

        for(列 = 0; 列 < 128; 列++)  // 循环128列
        {
            OLED写数据(0x00);  // 写入0，清屏
        }
    }
}

void main()  // 主函数
