## 八、传感器应用

### 8.1 温度传感器DS18B20

#### 8.1.1 DS18B20原理

DS18B20是一种数字温度传感器，具有以下特点：
- **温度范围**：-55℃到+125℃
- **精度**：±0.5℃
- **接口方式**：单总线接口
- **供电方式**：外部供电或寄生供电

#### 8.1.2 DS18B20温度读取

```c
#include <reg52.h>  // 包含51单片机头文件

sbit DS18B20_DQ = P3^7;  // 定义DS18B20数据引脚

void 延时(unsigned int 延时时间);  // 延时函数声明

void DS18B20复位()  // DS18B20复位函数
{
    DS18B20_DQ = 1;  // 数据线高电平
    延时(10);  // 延时

    DS18B20_DQ = 0;  // 数据线低电平
    延时(600);  // 延时480us以上

    DS18B20_DQ = 1;  // 数据线高电平
    延时(100);  // 延时

    while(DS18B20_DQ);  // 等待DS18B20响应
    // 等待数据线变为低电平

    while(!DS18B20_DQ);  // 等待DS18B20释放
    // 等待数据线变为高电平
}

void DS18B20写字节(unsigned char 字节)  // DS18B20写字节函数
{
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环8位
    {
        DS18B20_DQ = 0;  // 数据线低电平
        延时(10);  // 延时

        if(字节 & 0x01)  // 判断最低位
        {
            DS18B20_DQ = 1;  // 数据线高电平
        }
        // 最低位为0时保持低电平

        延时(60);  // 延时
        DS18B20_DQ = 1;  // 数据线高电平
        延时(10);  // 延时

        字节 >>= 1;  // 字节右移1位
        // 准备发送下一位
    }
}

unsigned char DS18B20读字节()  // DS18B20读字节函数
{
    unsigned char 字节 = 0;  // 定义字节变量
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环8位
    {
        字节 >>= 1;  // 字节右移1位
        // 准备接收下一位

        DS18B20_DQ = 0;  // 数据线低电平
        延时(10);  // 延时

        DS18B20_DQ = 1;  // 数据线高电平
        延时(10);  // 延时

        if(DS18B20_DQ)  // 判断数据线状态
        {
            字节 |= 0x80;  // 设置最高位
        }
        // 数据线为高电平时设置最高位

        延时(50);  // 延时
    }

    return 字节;  // 返回读取的字节
}

float DS18B20读取温度()  // DS18B20读取温度函数
{
    unsigned char 温度低8位;  // 定义温度低8位变量
    unsigned char 温度高8位;  // 定义温度高8位变量
    unsigned int 温度值;  // 定义温度值变量
    float 温度;  // 定义温度变量

    DS18B20复位();  // 复位DS18B20
    DS18B20写字节(0xCC);  // 跳过ROM
    DS18B20写字节(0x44);  // 启动温度转换

    延时(100000);  // 等待温度转换完成

    DS18B20复位();  // 复位DS18B20
    DS18B20写字节(0xCC);  // 跳过ROM
    DS18B20写字节(0xBE);  // 读取暂存器

    温度低8位 = DS18B20读字节();  // 读取温度低8位
    温度高8位 = DS18B20读字节();  // 读取温度高8位

    温度值 = (温度高8位 << 8) | 温度低8位;  // 组合温度值
    // 将高8位和低8位组合成16位温度值

    温度 = 温度值 * 0.0625;  // 计算温度值
    // DS18B20的精度为0.0625℃
    // 温度值 = 16位温度值 × 0.0625

    return 温度;  // 返回温度值
}

void main()  // 主函数
{
    float 当前温度;  // 定义当前温度变量

    while(1)  // 无限循环
    {
        当前温度 = DS18B20读取温度();  // 读取温度
        // 调用DS18B20读取温度函数

        // 可以将温度值显示到LCD或串口
        // 这里只是示例，实际应用需要添加显示代码
    }
}

