## 九、存储器应用

### 9.1 EEPROM读写

#### 9.1.1 EEPROM原理

EEPROM（电可擦除可编程只读存储器）是一种非易失性存储器：
- **存储特性**：掉电后数据不丢失
- **擦写次数**：通常为10万次以上
- **存储容量**：通常为几KB到几十KB
- **接口方式**：I2C或SPI接口

#### 9.1.2 AT24C02读写

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义I2C引脚
sbit I2C_SCL = P2^1;  // I2C时钟线
sbit I2C_SDA = P2^0;  // I2C数据线

void 延时(unsigned int 延时时间);  // 延时函数声明

void I2C起始()  // I2C起始信号函数
{
    I2C_SDA = 1;  // 数据线高电平
    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SDA = 0;  // 数据线低电平
    延时(10);  // 延时
    I2C_SCL = 0;  // 时钟线低电平
    // 产生起始信号
}

void I2C停止()  // I2C停止信号函数
{
    I2C_SDA = 0;  // 数据线低电平
    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SDA = 1;  // 数据线高电平
    延时(10);  // 延时
    // 产生停止信号
}

void I2C发送字节(unsigned char 字节)  // I2C发送字节函数
{
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环发送8位
    {
        if(字节 & 0x80)  // 判断最高位
        {
            I2C_SDA = 1;  // 数据线高电平
        }
        else  // 最高位为0
        {
            I2C_SDA = 0;  // 数据线低电平
        }

        I2C_SCL = 1;  // 时钟线高电平
        延时(10);  // 延时
        I2C_SCL = 0;  // 时钟线低电平
        延时(10);  // 延时

        字节 <<= 1;  // 字节左移1位
        // 准备发送下一位
    }

    I2C_SDA = 1;  // 数据线高电平
    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SCL = 0;  // 时钟线低电平
    // 等待应答信号
}

unsigned char I2C接收字节()  // I2C接收字节函数
{
    unsigned char 字节 = 0;  // 定义字节变量
    unsigned char 位计数器;  // 定义位计数器

    I2C_SDA = 1;  // 数据线高电平
    // 准备接收数据

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环接收8位
    {
        字节 <<= 1;  // 字节左移1位
        // 准备接收下一位

        I2C_SCL = 1;  // 时钟线高电平
        延时(10);  // 延时

        if(I2C_SDA)  // 判断数据线状态
        {
            字节 |= 0x01;  // 设置最低位
        }
        // 数据线为高电平时设置最低位

        I2C_SCL = 0;  // 时钟线低电平
        延时(10);  // 延时
    }

    return 字节;  // 返回接收的字节
}

void I2C发送应答(unsigned char 应答)  // I2C发送应答函数
{
    I2C_SDA = 应答;  // 设置应答信号
    // 0表示应答，1表示非应答

    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SCL = 0;  // 时钟线低电平
    延时(10);  // 延时
    // 发送应答信号
}

void AT24C02写入字节(unsigned char 地址, unsigned char 数据)  // AT24C02写入字节函数
{
    I2C起始();  // 发送起始信号
    I2C发送字节(0xA0);  // 发送AT24C02写地址
    // 0xA0 = 10100000
    // 设备地址为1010，写操作为0

    I2C发送字节(地址);  // 发送存储地址
    // 指定要写入的地址

    I2C发送字节(数据);  // 发送数据
    // 写入数据到指定地址

    I2C停止();  // 发送停止信号

    延时(10000);  // 延时等待写入完成
    // AT24C02写入需要一定时间
}

unsigned char AT24C02读取字节(unsigned char 地址)  // AT24C02读取字节函数
{
    unsigned char 数据;  // 定义数据变量

    I2C起始();  // 发送起始信号
    I2C发送字节(0xA0);  // 发送AT24C02写地址
    I2C发送字节(地址);  // 发送存储地址

    I2C起始();  // 发送起始信号
    I2C发送字节(0xA1);  // 发送AT24C02读地址
    // 0xA1 = 10100001
    // 设备地址为1010，读操作为1

    数据 = I2C接收字节();  // 接收数据
    I2C发送应答(1);  // 发送非应答
    // 表示不再接收数据

    I2C停止();  // 发送停止信号

    return 数据;  // 返回读取的数据
}

void main()  // 主函数
{
    unsigned char 写入数据 = 0x55;  // 定义写入数据
    unsigned char 读取数据;  // 定义读取数据

    AT24C02写入字节(0x00, 写入数据);  // 写入数据到地址0x00
    // 调用AT24C02写入字节函数

    读取数据 = AT24C02读取字节(0x00);  // 从地址0x00读取数据
    // 调用AT24C02读取字节函数

    while(1)  // 无限循环
    {
        // 主循环
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
