### 9.2 内部Flash读写

#### 9.2.1 内部Flash原理

51单片机的内部Flash存储器用于存储程序代码：
- **存储特性**：掉电后数据不丢失
- **擦写次数**：通常为10万次以上
- **存储容量**：通常为4KB到64KB
- **访问方式**：通过ISP/IAP接口

#### 9.2.2 内部Flash操作

```c
#include <reg52.h>  // 包含51单片机头文件

// ISP/IAP操作命令
#define ISP_IAP字节读 0x01  // 字节读命令
#define ISP_IAP字节编程 0x02  // 字节编程命令
#define ISP_IAP扇区擦除 0x03  // 扇区擦除命令

// ISP/IAP寄存器定义
sfr ISP_DATA = 0xE2;  // ISP/IAP数据寄存器
sfr ISP_ADDRH = 0xE3;  // ISP/IAP地址高字节
sfr ISP_ADDRL = 0xE4;  // ISP/IAP地址低字节
sfr ISP_CMD = 0xE5;  // ISP/IAP命令寄存器
sfr ISP_TRIG = 0xE6;  // ISP/IAP触发寄存器
sfr ISP_CONTR = 0xE7;  // ISP/IAP控制寄存器

void ISP_IAP使能(unsigned char 命令)  // ISP/IAP使能函数
{
    ISP_CONTR = 0x80;  // 使能ISP/IAP
    // 0x80 = 10000000
    // ISPEN=1: 使能ISP/IAP操作

    ISP_CMD = 命令;  // 设置ISP/IAP命令
    // 设置要执行的操作
}

void ISP_IAP禁止()  // ISP/IAP禁止函数
{
    ISP_CONTR = 0x00;  // 禁止ISP/IAP
    // 0x00 = 00000000
    // ISPEN=0: 禁止ISP/IAP操作

    ISP_CMD = 0x00;  // 清零ISP/IAP命令
    // 清零命令寄存器
}

void ISP_IAP触发()  // ISP/IAP触发函数
{
    ISP_TRIG = 0x46;  // 触发ISP/IAP操作
    // 0x46 = 01000110
    // 第一个触发字节

    ISP_TRIG = 0xB9;  // 触发ISP/IAP操作
    // 0xB9 = 10111001
    // 第二个触发字节
    // 触发ISP/IAP操作执行
}

unsigned char ISP_IAP读取字节(unsigned int 地址)  // ISP/IAP读取字节函数
{
    unsigned char 数据;  // 定义数据变量

    ISP_ADDRH = 地址 >> 8;  // 设置地址高字节
    // 将地址右移8位，得到高字节

    ISP_ADDRL = 地址 & 0xFF;  // 设置地址低字节
    // 将地址与0xFF进行与运算，得到低字节

    ISP_IAP使能(ISP_IAP字节读);  // 使能ISP/IAP字节读
    // 设置命令为字节读

    ISP_IAP触发();  // 触发ISP/IAP操作
    // 执行字节读操作

    数据 = ISP_DATA;  // 读取数据
    // 从ISP_DATA寄存器读取数据

    ISP_IAP禁止();  // 禁止ISP/IAP
    // 禁止ISP/IAP操作

    return 数据;  // 返回读取的数据
}

void ISP_IAP写入字节(unsigned int 地址, unsigned char 数据)  // ISP/IAP写入字节函数
{
    ISP_ADDRH = 地址 >> 8;  // 设置地址高字节
    ISP_ADDRL = 地址 & 0xFF;  // 设置地址低字节

    ISP_DATA = 数据;  // 设置要写入的数据
    // 将数据写入ISP_DATA寄存器

    ISP_IAP使能(ISP_IAP字节编程);  // 使能ISP/IAP字节编程
    // 设置命令为字节编程

    ISP_IAP触发();  // 触发ISP/IAP操作
    // 执行字节编程操作

    ISP_IAP禁止();  // 禁止ISP/IAP
    // 禁止ISP/IAP操作
}

void ISP_IAP扇区擦除(unsigned int 地址)  // ISP/IAP扇区擦除函数
{
    ISP_ADDRH = 地址 >> 8;  // 设置地址高字节
    ISP_ADDRL = 地址 & 0xFF;  // 设置地址低字节

    ISP_IAP使能(ISP_IAP扇区擦除);  // 使能ISP/IAP扇区擦除
    // 设置命令为扇区擦除

    ISP_IAP触发();  // 触发ISP/IAP操作
    // 执行扇区擦除操作

    ISP_IAP禁止();  // 禁止ISP/IAP
    // 禁止ISP/IAP操作
}

void main()  // 主函数
{
    unsigned int 写入地址 = 0x2000;  // 定义写入地址
    unsigned char 写入数据 = 0xAA;  // 定义写入数据
    unsigned char 读取数据;  // 定义读取数据

    ISP_IAP扇区擦除(写入地址);  // 擦除扇区
    // 调用ISP/IAP扇区擦除函数

    ISP_IAP写入字节(写入地址, 写入数据);  // 写入数据
    // 调用ISP/IAP写入字节函数

    读取数据 = ISP_IAP读取字节(写入地址);  // 读取数据
    // 调用ISP/IAP读取字节函数

    while(1)  // 无限循环
    {
        // 主循环
    }
}
