## 十、通信协议

### 10.1 I2C通信

#### 10.1.1 I2C通信原理

I2C（Inter-Integrated Circuit）是一种串行通信协议：
- **通信方式**：双线制（SDA数据线、SCL时钟线）
- **通信速率**：标准模式100kbps，快速模式400kbps
- **寻址方式**：7位地址或10位地址
- **多主机**：支持多主机通信

#### 10.1.2 I2C通信代码

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义I2C引脚
sbit I2C_SCL = P2^1;  // I2C时钟线
sbit I2C_SDA = P2^0;  // I2C数据线

void 延时(unsigned int 延时时间);  // 延时函数声明

void I2C起始()  // I2C起始信号函数
{
    I2C_SDA = 1;  // 数据线高电平
    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SDA = 0;  // 数据线低电平
    延时(10);  // 延时
    I2C_SCL = 0;  // 时钟线低电平
    // 产生起始信号
}

void I2C停止()  // I2C停止信号函数
{
    I2C_SDA = 0;  // 数据线低电平
    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SDA = 1;  // 数据线高电平
    延时(10);  // 延时
    // 产生停止信号
}

void I2C发送字节(unsigned char 字节)  // I2C发送字节函数
{
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环发送8位
    {
        if(字节 & 0x80)  // 判断最高位
        {
            I2C_SDA = 1;  // 数据线高电平
        }
        else  // 最高位为0
        {
            I2C_SDA = 0;  // 数据线低电平
        }

        I2C_SCL = 1;  // 时钟线高电平
        延时(10);  // 延时
        I2C_SCL = 0;  // 时钟线低电平
        延时(10);  // 延时

        字节 <<= 1;  // 字节左移1位
        // 准备发送下一位
    }

    I2C_SDA = 1;  // 数据线高电平
    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SCL = 0;  // 时钟线低电平
    // 等待应答信号
}

unsigned char I2C接收字节()  // I2C接收字节函数
{
    unsigned char 字节 = 0;  // 定义字节变量
    unsigned char 位计数器;  // 定义位计数器

    I2C_SDA = 1;  // 数据线高电平
    // 准备接收数据

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环接收8位
    {
        字节 <<= 1;  // 字节左移1位
        // 准备接收下一位

        I2C_SCL = 1;  // 时钟线高电平
        延时(10);  // 延时

        if(I2C_SDA)  // 判断数据线状态
        {
            字节 |= 0x01;  // 设置最低位
        }
        // 数据线为高电平时设置最低位

        I2C_SCL = 0;  // 时钟线低电平
        延时(10);  // 延时
    }

    return 字节;  // 返回接收的字节
}

void I2C发送应答(unsigned char 应答)  // I2C发送应答函数
{
    I2C_SDA = 应答;  // 设置应答信号
    // 0表示应答，1表示非应答

    I2C_SCL = 1;  // 时钟线高电平
    延时(10);  // 延时
    I2C_SCL = 0;  // 时钟线低电平
    延时(10);  // 延时
    // 发送应答信号
}

void I2C写入数据(unsigned char 设备地址, unsigned char 寄存器地址, unsigned char 数据)  // I2C写入数据函数
{
    I2C起始();  // 发送起始信号
    I2C发送字节(设备地址);  // 发送设备地址（写）
    I2C发送字节(寄存器地址);  // 发送寄存器地址
    I2C发送字节(数据);  // 发送数据
    I2C停止();  // 发送停止信号
}

unsigned char I2C读取数据(unsigned char 设备地址, unsigned char 寄存器地址)  // I2C读取数据函数
{
    unsigned char 数据;  // 定义数据变量

    I2C起始();  // 发送起始信号
    I2C发送字节(设备地址);  // 发送设备地址（写）
    I2C发送字节(寄存器地址);  // 发送寄存器地址

    I2C起始();  // 发送起始信号
    I2C发送字节(设备地址 | 0x01);  // 发送设备地址（读）
    // 设备地址 | 0x01：将最低位设置为1，表示读操作

    数据 = I2C接收字节();  // 接收数据
    I2C发送应答(1);  // 发送非应答
    I2C停止();  // 发送停止信号

    return 数据;  // 返回读取的数据
}

void main()  // 主函数
{
    unsigned char 设备地址 = 0xA0;  // 定义设备地址
    unsigned char 寄存器地址 = 0x00;  // 定义寄存器地址
    unsigned char 写入数据 = 0x55;  // 定义写入数据
    unsigned char 读取数据;  // 定义读取数据

    I2C写入数据(设备地址, 寄存器地址, 写入数据);  // 写入数据
    // 调用I2C写入数据函数

    读取数据 = I2C读取数据(设备地址, 寄存器地址);  // 读取数据
    // 调用I2C读取数据函数

    while(1)  // 无限循环
    {
        // 主循环
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

### 10.2 SPI通信

#### 10.2.1 SPI通信原理

SPI（Serial Peripheral Interface）是一种串行通信协议：
- **通信方式**：四线制（MOSI、MISO、SCK、CS）
- **通信速率**：可达数Mbps
- **通信模式**：4种时钟极性和相位模式
- **全双工**：支持全双工通信

#### 10.2.2 SPI通信代码

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义SPI引脚
sbit SPI_MOSI = P1^5;  // SPI主出从入
sbit SPI_MISO = P1^6;  // SPI主入从出
sbit SPI_SCK = P1^7;  // SPI时钟
sbit SPI_CS = P1^4;  // SPI片选

void 延时(unsigned int 延时时间);  // 延时函数声明

void SPI初始化()  // SPI初始化函数
{
    SPI_MOSI = 1;  // MOSI初始高电平
    SPI_SCK = 0;  // SCK初始低电平
    SPI_CS = 1;  // CS初始高电平（未选中）
    // 初始化SPI引脚
}

unsigned char SPI发送接收字节(unsigned char 发送数据)  // SPI发送接收字节函数
{
    unsigned char 接收数据 = 0;  // 定义接收数据变量
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环8位
    {
        SPI_MOSI = 发送数据 & 0x80;  // 发送最高位
        // 将发送数据的最高位输出到MOSI

        SPI_SCK = 1;  // 时钟上升沿
        延时(10);  // 延时

        接收数据 <<= 1;  // 接收数据左移1位
        // 准备接收下一位

        if(SPI_MISO)  // 判断MISO状态
        {
            接收数据 |= 0x01;  // 设置最低位
        }
        // MISO为高电平时设置最低位

        SPI_SCK = 0;  // 时钟下降沿
        延时(10);  // 延时

        发送数据 <<= 1;  // 发送数据左移1位
        // 准备发送下一位
    }

    return 接收数据;  // 返回接收的数据
}

void SPI写入数据(unsigned char 寄存器地址, unsigned char 数据)  // SPI写入数据函数
{
    SPI_CS = 0;  // 选中设备
    // 片选信号低电平有效

    SPI发送接收字节(寄存器地址);  // 发送寄存器地址
    // 调用SPI发送接收字节函数

    SPI发送接收字节(数据);  // 发送数据
    // 调用SPI发送接收字节函数

    SPI_CS = 1;  // 取消选中
    // 片选信号高电平无效
}

unsigned char SPI读取数据(unsigned char 寄存器地址)  // SPI读取数据函数
{
    unsigned char 数据;  // 定义数据变量

    SPI_CS = 0;  // 选中设备
    // 片选信号低电平有效

    SPI发送接收字节(寄存器地址 | 0x80);  // 发送寄存器地址（读）
    // 寄存器地址 | 0x80：将最高位设置为1，表示读操作

    数据 = SPI发送接收字节(0x00);  // 读取数据
    // 调用SPI发送接收字节函数

    SPI_CS = 1;  // 取消选中
    // 片选信号高电平无效

    return 数据;  // 返回读取的数据
}

void main()  // 主函数
{
    unsigned char 寄存器地址 = 0x00;  // 定义寄存器地址
    unsigned char 写入数据 = 0x55;  // 定义写入数据
    unsigned char 读取数据;  // 定义读取数据

    SPI初始化();  // 初始化SPI
    // 调用SPI初始化函数

    SPI写入数据(寄存器地址, 写入数据);  // 写入数据
    // 调用SPI写入数据函数

    读取数据 = SPI读取数据(寄存器地址);  // 读取数据
    // 调用SPI读取数据函数

    while(1)  // 无限循环
    {
        // 主循环
    }
}

void 延时(unsigned int 延时时间)  // 延时函数
{
    unsigned int 计数器;

    for(计数器 = 0; 计数器 < 延时时间; 计数器++)
    {
        // 空循环
    }
}
```

