## 十一、综合项目

### 11.1 智能温控系统

#### 11.1.1 项目概述

智能温控系统是一个基于51单片机的温度控制系统：
- **温度检测**：使用DS18B20温度传感器
- **温度显示**：使用LCD1602显示温度
- **温度控制**：使用继电器控制加热器
- **按键设置**：使用按键设置目标温度

#### 11.1.2 项目代码

```c
#include <reg52.h>  // 包含51单片机头文件

// 定义LCD1602引脚
sbit LCD_RS = P2^0;  // 寄存器选择
sbit LCD_RW = P2^1;  // 读写选择
sbit LCD_EN = P2^2;  // 使能信号
#define LCD_DATA P0  // LCD数据端口

// 定义DS18B20引脚
sbit DS18B20_DQ = P3^7;  // DS18B20数据引脚

// 定义按键引脚
sbit 设置按键 = P3^0;  // 设置按键
sbit 增加按键 = P3^1;  // 增加按键
sbit 减少按键 = P3^2;  // 减少按键

// 定义继电器引脚
sbit 继电器 = P1^0;  // 继电器控制引脚

// 定义变量
float 当前温度 = 0.0;  // 当前温度
float 目标温度 = 25.0;  // 目标温度
unsigned char 设置模式 = 0;  // 设置模式标志

void 延时(unsigned int 延时时间);  // 延时函数声明

// LCD1602函数
void LCD写命令(unsigned char 命令)  // LCD写命令函数
{
    LCD_RS = 0;  // 选择命令寄存器
    LCD_RW = 0;  // 选择写操作
    LCD_DATA = 命令;  // 输出命令
    LCD_EN = 1;  // 使能信号高电平
    延时(100);  // 延时
    LCD_EN = 0;  // 使能信号低电平
}

void LCD写数据(unsigned char 数据)  // LCD写数据函数
{
    LCD_RS = 1;  // 选择数据寄存器
    LCD_RW = 0;  // 选择写操作
    LCD_DATA = 数据;  // 输出数据
    LCD_EN = 1;  // 使能信号高电平
    延时(100);  // 延时
    LCD_EN = 0;  // 使能信号低电平
}

void LCD初始化()  // LCD初始化函数
{
    延时(15000);  // 等待LCD上电稳定
    LCD写命令(0x38);  // 设置8位数据接口，两行显示
    LCD写命令(0x0C);  // 显示开，光标关，闪烁关
    LCD写命令(0x06);  // 文字不动，地址自动加1
    LCD写命令(0x01);  // 清屏
    延时(2000);  // 等待清屏完成
}

void LCD显示字符串(unsigned char 行, unsigned char 列, unsigned char *字符串)  // LCD显示字符串函数
{
    unsigned char 地址;  // 定义地址变量

    if(行 == 0)  // 判断行号
    {
        地址 = 0x80 + 列;  // 第一行地址
    }
    else  // 第二行
    {
        地址 = 0xC0 + 列;  // 第二行地址
    }

    LCD写命令(地址);  // 设置显示地址

    while(*字符串 != '\0')  // 循环直到字符串结束
    {
        LCD写数据(*字符串);  // 写入字符
        字符串++;  // 指针加1
    }
}

// DS18B20函数
void DS18B20复位()  // DS18B20复位函数
{
    DS18B20_DQ = 1;  // 数据线高电平
    延时(10);  // 延时
    DS18B20_DQ = 0;  // 数据线低电平
    延时(600);  // 延时480us以上
    DS18B20_DQ = 1;  // 数据线高电平
    延时(100);  // 延时
    while(DS18B20_DQ);  // 等待DS18B20响应
    while(!DS18B20_DQ);  // 等待DS18B20释放
}

void DS18B20写字节(unsigned char 字节)  // DS18B20写字节函数
{
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环8位
    {
        DS18B20_DQ = 0;  // 数据线低电平
        延时(10);  // 延时

        if(字节 & 0x01)  // 判断最低位
        {
            DS18B20_DQ = 1;  // 数据线高电平
        }

        延时(60);  // 延时
        DS18B20_DQ = 1;  // 数据线高电平
        延时(10);  // 延时

        字节 >>= 1;  // 字节右移1位
    }
}

unsigned char DS18B20读字节()  // DS18B20读字节函数
{
    unsigned char 字节 = 0;  // 定义字节变量
    unsigned char 位计数器;  // 定义位计数器

    for(位计数器 = 0; 位计数器 < 8; 位计数器++)  // 循环8位
    {
        字节 >>= 1;  // 字节右移1位
        DS18B20_DQ = 0;  // 数据线低电平
        延时(10);  // 延时
        DS18B20_DQ = 1;  // 数据线高电平
        延时(10);  // 延时

        if(DS18B20_DQ)  // 判断数据线状态
        {
            字节 |= 0x80;  // 设置最高位
        }

        延时(50);  // 延时
    }

    return 字节;  // 返回读取的字节
}

float DS18B20读取温度()  // DS18B20读取温度函数
{
    unsigned char 温度低8位;  // 定义温度低8位变量
    unsigned char 温度高8位;  // 定义温度高8位变量
    unsigned int 温度值;  // 定义温度值变量
    float 温度;  // 定义温度变量

    DS18B20复位();  // 复位DS18B20
    DS18B20写字节(0xCC);  // 跳过ROM
    DS18B20写字节(0x44);  // 启动温度转换

    延时(100000);  // 等待温度转换完成

    DS18B20复位();  // 复位DS18B20
    DS18B20写字节(0xCC);  // 跳过ROM
    DS18B20写字节(0xBE);  // 读取暂存器

    温度低8位 = DS18B20读字节();  // 读取温度低8位
    温度高8位 = DS18B20读字节();  // 读取温度高8位

    温度值 = (温度高8位 << 8) | 温度低8位;  // 组合温度值
    温度 = 温度值 * 0.0625;  // 计算温度值

    return 温度;  // 返回温度值
}

// 按键处理函数
void 按键处理()  // 按键处理函数
{
    if(设置按键 == 0)  // 检测设置按键
    {
        延时(1000);  // 消抖

        if(设置按键 == 0)  // 确认按键按下
        {
            设置模式 = ~设置模式;  // 切换设置模式
            // 设置模式取反

            while(设置按键 == 0);  // 等待按键释放
        }
    }

    if(设置模式 == 1)  // 判断是否在设置模式
    {
        if(增加按键 == 0)  // 检测增加按键
        {
            延时(1000);  // 消抖

            if(增加按键 == 0)  // 确认按键按下
            {
                目标温度 += 0.5;  // 目标温度加0.5
                // 增加目标温度

                if(目标温度 > 50.0)  // 判断是否超过最大值
                {
                    目标温度 = 50.0;  // 限制最大值
                }

                while(增加按键 == 0);  // 等待按键释放
            }
        }

        if(减少按键 == 0)  // 检测减少按键
        {
            延时(1000);  // 消抖

            if(减少按键 == 0)  // 确认按键按下
            {
                目标温度 -= 0.5;  // 目标温度减0.5
                // 减少目标温度

                if(目标温度 < 10.0)  // 判断是否低于最小值
                {
                    目标温度 = 10.0;  // 限制最小值
                }

                while(减少按键 == 0);  // 等待按键释放
            }
        }
    }
}

// 温度控制函数
void 温度控制()  // 温度控制函数
{
    if(当前温度 < 目标温度 - 1.0)  // 判断温度是否低于目标温度
    {
        继电器 = 0;  // 开启加热器
        // 温度低于目标温度时开启加热器
    }
    else if(当前温度 > 目标温度 + 1.0)  // 判断温度是否高于目标温度
    {
        继电器 = 1;  // 关闭加热器
        // 温度高于目标温度时关闭加热器
    }
    // 温度在目标温度±1.0范围内时保持当前状态
}

void main()  // 主函数
{
    LCD初始化();  // 初始化LCD

    继电器 = 1;  // 继电器初始关闭
    // 继电器低电平有效

    LCD显示字符串(0, 0, "Temp Control");  // 显示标题

    while(1)  // 无限循环
    {
        当前温度 = DS18B20读取温度();  // 读取温度
        // 调用DS18B20读取温度函数

        按键处理();  // 处理按键
        // 调用按键处理函数

        温度控制();  // 控制温度
        // 调用温度控制函数

